class TaskManager {
  // key = priority << 17 | taskId, so the largest key is the highest priority (ties: highest
  // taskId)
  private final TreeSet<Long> queue = new TreeSet<>();
  private final Map<Integer, int[]> tasks = new HashMap<>(); // taskId -> {userId, priority}

  public TaskManager(List<List<Integer>> tasks) {
    for (List<Integer> t : tasks) add(t.get(0), t.get(1), t.get(2));
  }

  public void add(int userId, int taskId, int priority) {
    tasks.put(taskId, new int[] {userId, priority});
    queue.add(key(priority, taskId));
  }

  public void edit(int taskId, int newPriority) {
    int[] t = tasks.get(taskId);
    queue.remove(key(t[1], taskId));
    t[1] = newPriority;
    queue.add(key(newPriority, taskId));
  }

  public void rmv(int taskId) {
    int[] t = tasks.remove(taskId);
    queue.remove(key(t[1], taskId));
  }

  public int execTop() {
    if (queue.isEmpty()) return -1;
    long top = queue.pollLast();
    int taskId = (int) (top & ((1 << 17) - 1));
    return tasks.remove(taskId)[0];
  }

  private long key(int priority, int taskId) {
    return ((long) priority << 17) | taskId;
  }
}

